func Controller(inputPath string, outputPath string, s3Client *utils.S3Client, bucket string, size uint64, callback func(), warn func(int)) error {
    if size > 10*1000*1024*1024 {
        return ParseJsonToParquet(inputPath, outputPath, s3Client, bucket, size, callback, warn)
    } else {
        return ParseJsonToJson(inputPath, outputPath, s3Client, bucket, size, callback, warn)
    }
}

type Column struct {
    Name   string  `json:"name"`
    Type   string  `json:"type"` // int, float, string, bool, table
    Schema *Schema `json:"schema,omitempty"`
}

type Table struct {
    Schema Schema `json:"schema"`
    Rows   Row    `json:"rows"`
}

type Schema struct {
    Columns []Column `json:"columns"`
}

type Row [][]interface{}

func inferType(value interface{}) string {
    switch v := value.(type) {
    case float64:
        // JSON numbers become float64 by default
        if v == float64(int(v)) {
            return "int"
        }
        return "float"
    case string:
        return "string"
    case bool:
        return "bool"
    case map[string]interface{}:
        return "table"
    case []interface{}:
        return "array"
    default:
        return "string"
    }
}

