func detectJSONType(data []byte) string {
    data = bytes.TrimSpace(data)
    if len(data) == 0 {
        return "unknown"
    }
    if data[0] == '[' {
        return "array"
    }
    if data[0] == '{' {
        if bytes.Contains(data, []byte("}\n{")) {
            return "ndjson"
        }
        return "object"
    }
    return "unknown"
}

func ParseJsonToJson(inputPath string, outputPath string, s3Client *utils.S3Client, bucket string, size uint64, callback func(), warn func(int)) error {
    const CHUNK_SIZE = 5 * 1024 * 1024 // 5 MB
    downloadedData := []byte{}
    for offset := uint64(0); offset < size; offset += CHUNK_SIZE {
        end := min((offset+CHUNK_SIZE)-1, size-1)
        var wg sync.WaitGroup
        resultCh := make(chan []byte, 1)
        errCh := make(chan error, 1)
        wg.Add(1)
        go func(offset, end uint64) {
            defer wg.Done()
            res, err := s3Client.GetObjectBytesFromRange(inputPath, bucket, uint(offset), uint(end), nil)
            if err != nil {
                errCh <- err
                return
            }
            resultCh <- res
        }(offset, end)
        wg.Wait()
        close(resultCh)
        close(errCh)
        if err := <-errCh; err != nil {
            return err
        }
        if chunk, ok := <-resultCh; ok {
            downloadedData = append(downloadedData, chunk...)
            fmt.Println("Downloaded chunk:", offset, "to", end)
        }
    }
    fmt.Println("Total bytes downloaded:", len(downloadedData))
    var table Table
    jsonType := detectJSONType(downloadedData)
    fmt.Println("Detected JSON type:", jsonType)
    switch jsonType {
    case "array", "object":
        var raw interface{}
        if err := json.Unmarshal(downloadedData, &raw); err != nil {
            return err
        }
        table.Rows = normalizeJSON(raw, &table.Schema, 0)
    case "ndjson":
        table.Rows = parseNDJSON(downloadedData, &table.Schema)
    default:
        return fmt.Errorf("unknown JSON type")
    }
    var fileToSend []byte
    schemaBytes, _ := json.Marshal(table.Schema)
    fileToSend = append(fileToSend, schemaBytes...)
    fileToSend = append(fileToSend, '\n')
    lineNumber := uint64(1)
    totalLines := uint64(len(table.Rows))
    for len(table.Rows) > 0 {
        row := table.Rows[0]
        table.Rows[0] = nil
        table.Rows = table.Rows[1:]
        jsonBytes, _ := json.Marshal(row)
        rowBytes := append([]byte(strconv.FormatUint(lineNumber, 10)), jsonBytes...)
        fileToSend = append(fileToSend, rowBytes...)
        if lineNumber < totalLines {
            fileToSend = append(fileToSend, '\n')
        }
        lineNumber++
    }
    singedObjectURL, err := s3Client.GenUploadURL(bucket, outputPath+".tarrajson", 3600)
    if err != nil {
        return fmt.Errorf("failed to generate signed URL: %v", err)
    }
    req, err := http.NewRequest("PUT", singedObjectURL, bytes.NewReader(fileToSend))
    if err != nil {
        return fmt.Errorf("failed to create PUT request: %v", err)
    }
    req.Header.Set("Content-Type", "application/x-tarrajson")
    req.ContentLength = int64(len(fileToSend))
    client := &http.Client{}
    resp, err := client.Do(req)
    if err != nil {
        return fmt.Errorf("failed to upload normalized JSON: %v", err)
    }
    defer resp.Body.Close()
    if resp.StatusCode != http.StatusOK && resp.StatusCode != http.StatusCreated {
        return fmt.Errorf("upload failed with status: %s", resp.Status)
    }
    fmt.Println("Normalized JSON uploaded successfully to", outputPath)
    callback()
    return nil
}
